import React from 'react';
import './Projects.css';

const PROJECTS = [
  {
    title: 'ExploitXplorers',
    desc: 'A community platform for cybersecurity awareness and hands-on knowledge for students, fostering a secure digital environment.',
    tags: ['MERN Stack', 'Cybersecurity', 'UI/UX'],
    href: '#',
    bg: '#111',
    light: false,
  },
  {
    title: 'Priscripto',
    desc: 'AI-powered medical appointment booking system designed for healthcare accessibility and streamlined scheduling.',
    tags: ['AI', 'React', 'Node.js', 'MongoDB'],
    href: '#',
    bg: '#f81927',
    light: false,
  },
  {
    title: 'Hospital Booking System',
    desc: 'A comprehensive healthcare scheduling solution for booking and managing doctor appointments efficiently.',
    tags: ['MERN Stack', 'Healthcare', 'UI/UX'],
    href: '#',
    bg: '#eee',
    light: true,
  },
  {
    title: 'Blog System',
    desc: 'A dynamic space for writers and creators to share knowledge, publish articles, and stay updated on latest trends.',
    tags: ['React', 'Express', 'Tailwind'],
    href: '#',
    bg: '#111',
    light: false,
  },
];

export default function Projects() {
  return (
    <section className="py-section" id="projects">
      <div className="container">
        <h2 className="font-display text-3xl font-semibold lg:text-4xl">Featured Projects</h2>
        <p className="text-xl lg:text-2xl mt-2 text-gray-600">
          A selection of real-world products designed, built, and shipped — each solving a concrete problem.
        </p>
      </div>

      <div className="overflow-auto mt-8">
        <div className="container">
          <div className="projects-grid grid gap-px bg-black border border-black md:grid-cols-2 lg:grid-cols-4">
            {PROJECTS.map((proj) => (
              <a
                key={proj.title}
                href={proj.href}
                className="project-card group bg-white flex flex-col"
              >
                {/* Visual area - Placeholder for image */}
                <div className="project-card__visual flex-none aspect-video flex items-center justify-center overflow-hidden" style={{ background: proj.bg }}>
                   <span className={`font-display font-black text-2xl uppercase tracking-tighter opacity-20 ${proj.light ? 'text-black' : 'text-white'}`}>
                      {proj.title}
                    </span>
                </div>

                {/* Content */}
                <div className="p-8 flex-1 flex flex-col border-t border-black">
                  <h3 className="font-display text-xl lg:text-2xl font-medium">{proj.title}</h3>
                  <p className="text-lg mt-2 text-gray-600 flex-1 line-clamp-3">{proj.desc}</p>
                  <div className="project-card__tags mt-6 flex flex-wrap gap-2">
                    {proj.tags.map((tag) => (
                      <span key={tag} className="tag font-mono text-[10px] uppercase px-2 py-1 border border-black text-black">
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              </a>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
